package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="spms_rating_action",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_action_request",columnNames={"agency_id","rating_case_id","request_key"}))public class PerformanceRatingAction extends RspAuditedEntity{@Column(name="rating_case_id",nullable=false,length=36)private String ratingCaseId;@Column(name="subject_id",nullable=false,length=36)private String subjectId;@Column(name="action_type",nullable=false,length=50)private String actionType;@Column(name="request_key",nullable=false,length=100)private String requestKey;@Column(name="actor_employee_no",nullable=false,length=100)private String actorEmployeeNo;@Column(length=2000)private String reason;@Column(name="acted_at",nullable=false)private Instant actedAt;protected PerformanceRatingAction(){}public PerformanceRatingAction(String a,String c,String subject,String action,String key,String actor,String reason,Instant at){super(a);ratingCaseId=requiredText(c,"ratingCaseId");subjectId=requiredText(subject,"subjectId");actionType=requiredText(action,"actionType");requestKey=requiredText(key,"requestKey");actorEmployeeNo=requiredText(actor,"actorEmployeeNo");this.reason=optionalText(reason);actedAt=at;}public String getRatingCaseId(){return ratingCaseId;}public String getSubjectId(){return subjectId;}public String getActionType(){return actionType;}public String getRequestKey(){return requestKey;}public String getActorEmployeeNo(){return actorEmployeeNo;}public String getReason(){return reason;}public Instant getActedAt(){return actedAt;}}
